fn four_times(n: i32) -> i32 {
    4 * n
}

fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Assuming N is positive and less than 1000 as per the problem statement
    if N > 0 && N < 1000 {
        sum[0] = four_times(N);
    }
}

